# -*- coding: utf-8 -*-
from zh_src.art_lib import build

build("esguince-tobillo-sigue-fallando", dict(
 categoria="踝关节扭伤",
 titulo="踝关节扭伤：总是“打软”的四个原因",
 resumen="为什么没有痊愈好的踝关节扭伤会留下总是崴脚的踝关节，以及如何治疗。",
 descripcion="没有痊愈好的踝关节扭伤总是“打软”的四个原因及治疗：超声、力量和平衡训练。胡里奥·德拉莫雷纳医生，马德里。",
 entradilla="踝关节扭伤之所以总是“打软”，是因为当初只被当作普通崴脚处理、没有训练平衡和力量，或者遗留了一处没人去找的合并损伤。治疗包括门诊超声、力量和平衡训练方案，以及在韧带不愈合时使用 PRP（富血小板血浆）。胡里奥·德拉莫雷纳医生在 Memorial Publio Cordón 医院（马德里波苏埃洛-德阿拉尔孔）再生疗法与运动医学科治疗这一问题。",
 imagen_alt="胡里奥·德拉莫雷纳医生在 Memorial Publio Cordón 医院的门诊指着踝关节磁共振",
 temas=["踝关节扭伤", "慢性踝关节不稳", "距腓前韧带损伤"],
 secciones=[
  ("“自从那次扭伤，我的脚踝就再也不一样了”",
   "<p>这是门诊每周都会听到的话。踝关节扭伤是最常见的损伤之一，同时也是最常没有痊愈好的损伤之一。它发生在脚扭转时，几乎总是向内翻，损伤了稳定关节的韧带，多数情况下是外侧韧带。</p><p>任何人都可能发生：从路沿下来、上楼梯踩空，或在比赛中。大多数扭伤通过功能性治疗可以很好地恢复，但如果恢复不完全，就会留下不稳定的踝关节，反复崴脚。下面是最常见的四个原因。</p>"),
  ("1. 只被当作“普通崴脚”",
   "<p>没有诊断的明显扭伤，可能使韧带松弛。并非所有扭伤都一样：体格检查可以确定哪些韧带受累，以及是否需要 X 线检查来排除骨折，而超声可以显示韧带的状态并对损伤分级。没有这样的诊断，很容易过早地恢复活动，或采用与真实严重程度不相符的治疗。</p>"),
  ("2. 没有训练平衡",
   "<p>扭伤之后，踝关节会失去“知道自己在哪里”的能力，也就是感知自身位置并及时对踩错的一步做出反应的能力。如果没有专门的平衡训练，这种能力无法正常恢复，踝关节在日常情境中就会再次崴脚。</p>"),
  ("3. 腿部缺乏力量",
   "<p>稳定踝关节的肌肉必须在恢复正常生活之前恢复，在重返运动之前更是如此。比已经过去的时间更重要的是，力量和平衡是否已经恢复。如果带着变弱的肌肉回归，韧带就失去了保护。</p>"),
  ("4. 遗漏了合并损伤",
   "<p>扭伤时，除了主要的韧带，软骨、肌腱或其他韧带也可能同时受损。如果没有去寻找这种合并损伤，即使扭伤看似已经痊愈，踝关节仍会疼痛或“打软”。门诊超声有助于发现它。</p>"),
  ("我们如何处理",
   "<p>没有痊愈好的扭伤是可以治疗的。门诊的处理方式包括：</p><ul><li><strong>同一次就诊中做超声</strong>，评估韧带的状态并寻找合并损伤。</li><li><strong>力量和平衡训练方案</strong>，恢复踝关节的稳定性，防止再次受伤。</li><li><strong>韧带不愈合时使用 PRP</strong>，通过超声引导注射应用。它取自患者自身的血液，无需手术或住院。</li></ul><p>当慢性不稳经过专门的训练方案仍没有改善时，会考虑手术选择。每个病例都会单独评估。您可以在<a href=\"/esguince-tobillo/\">踝关节扭伤</a>页面和<a href=\"/infiltraciones-ecoguiadas/\">超声引导注射</a>页面找到更多信息。</p>"),
  ("何时应当就医",
   "<p>如果脚不能着地或连续走不了四步，如果有明显肿胀或大片淤青，如果一到两周后疼痛仍没有改善，或者扭伤反复发生并感觉脚踝“打软”，就值得就医。胡里奥·德拉莫雷纳医生在马德里波苏埃洛-德阿拉尔孔 Memorial Publio Cordón 医院再生疗法与运动医学科评估这些损伤。</p>"),
 ],
 faq=[
  ("在马德里，哪位医生治疗没有痊愈好的踝关节扭伤？", "胡里奥·德拉莫雷纳医生，运动与体育医学专科医生，在马德里波苏埃洛-德阿拉尔孔 Memorial Publio Cordón 医院再生疗法与运动医学科治疗踝关节扭伤和不稳定的踝关节，同一次就诊中使用超声。"),
  ("为什么我总是崴同一只脚踝？", "通常是因为之前的扭伤没有完全恢复：韧带松弛、没有训练平衡、腿部缺乏力量，或者有未被诊断的合并损伤。"),
  ("陈旧的扭伤还能治疗吗？", "可以。通过超声进行评估，开具力量和平衡训练方案，如果韧带不愈合，可以使用 PRP。如果不稳持续存在，则考虑手术。"),
  ("踝关节扭伤后什么时候可以恢复运动？", "取决于损伤的级别：轻度扭伤约一到两周，严重扭伤则需要数周。比时间更重要的是，在恢复运动前先恢复力量和平衡。"),
 ]))

build("factores-crecimiento-evidencia", dict(
 categoria="再生疗法",
 titulo="PRP（富血小板血浆）：研究怎么说",
 resumen="关于 PRP（富血小板血浆）治疗骨关节炎、肌腱病和肩部的最佳综述和试验，附链接的摘要。",
 descripcion="研究如何看待 PRP（富血小板血浆）治疗膝关节骨关节炎、肌腱病和足底筋膜炎。",
 entradilla="PRP（富血小板血浆）释放取自患者自身血液的生长因子，是研究最多的再生治疗之一。科学证据最充分的适应证是轻中度膝关节骨关节炎，临床试验的综述显示，其缓解作用比透明质酸或皮质类固醇更明显、更持久。在臀肌肌腱病、网球肘、足底筋膜炎和肩袖手术中，也有积极的研究。这里我们概述主要的研究，并附上链接。",
 imagen_alt="正在进行的超声引导治疗",
 temas=["膝关节骨关节炎", "肌腱病", "肱骨外上髁炎", "足底筋膜炎", "肩袖撕裂"],
 secciones=[
  ("我们如何筛选研究",
   "<p>我们优先选择质量最高的来源：汇集了许多随机临床试验的系统综述和荟萃分析、欧洲专家共识，以及双盲临床试验。每项研究都用一句话概括，并链接到其原始发表页面。结果不利的研究也一并列出，因为诚实的信息是良好适应证判断的一部分。已被期刊撤稿的综述已被排除。</p>"),
  ("膝关节骨关节炎：证据最充分的适应证",
   "<ul><li><strong>欧洲共识（2024 年）。</strong>欧洲运动创伤学、膝关节外科和关节镜学会以最高推荐级别得出结论：有足够的证据支持在轻中度膝关节骨关节炎中使用，其效果比皮质类固醇持续更久，并且它可以作为注射治疗中的一线选择。<a href=\"https://doi.org/10.1002/ksa.12077\" rel=\"noopener\" target=\"_blank\">Laver 等，Knee Surgery, Sports Traumatology, Arthroscopy，2024 年</a>。</li><li><strong>与透明质酸对比。</strong>十五项双盲试验，1,632 名患者：12 个月时疼痛和功能的改善更大，差异具有临床意义。<a href=\"https://doi.org/10.1016/j.arthro.2025.06.033\" rel=\"noopener\" target=\"_blank\">Li 等，Arthroscopy，2025 年</a>。</li><li><strong>所有注射治疗的比较。</strong>四十八项试验，9,338 个膝关节：从 6 个月起，PRP 在疼痛和功能方面排名最佳，领先于透明质酸和皮质类固醇。<a href=\"https://doi.org/10.1016/j.arthro.2024.01.037\" rel=\"noopener\" target=\"_blank\">Jawanda 等，Arthroscopy，2024 年</a>。</li><li><strong>与皮质类固醇对比。</strong>在 3、6 和 9 个月时结果更好；每周一次、共三次注射优于单次注射。<a href=\"https://doi.org/10.1186/s12891-021-04308-3\" rel=\"noopener\" target=\"_blank\">McLarnon 和 Heron，BMC Musculoskeletal Disorders，2021 年</a>。</li><li><strong>与安慰剂对比。</strong>三十四项试验：获益超出安慰剂效应，并随时间增加，在 6 至 12 个月之间具有临床意义。<a href=\"https://doi.org/10.1177/1947603520931170\" rel=\"noopener\" target=\"_blank\">Filardo 等，Cartilage，2020 年</a>。</li></ul>"),
  ("臀肌肌腱病（髋部外侧疼痛）",
   "<ul><li><strong>与皮质类固醇的双盲试验。</strong>单次超声引导注射，3 个月时的改善更大。<a href=\"https://doi.org/10.1177/0363546517745525\" rel=\"noopener\" target=\"_blank\">Fitzpatrick 等，American Journal of Sports Medicine，2018 年</a>。</li><li><strong>两年随访。</strong>改善在 2 年时仍然保持，而皮质类固醇的效果不超过 24 周。<a href=\"https://doi.org/10.1177/0363546519826969\" rel=\"noopener\" target=\"_blank\">Fitzpatrick 等，American Journal of Sports Medicine，2019 年</a>。</li></ul>"),
  ("网球肘、足底筋膜炎和其他肌腱病",
   "<ul><li><strong>网球肘（肱骨外上髁炎）。</strong>皮质类固醇在第一个月缓解作用更大；PRP 在 3 和 6 个月时结果更好。<a href=\"https://doi.org/10.1016/j.jse.2023.04.018\" rel=\"noopener\" target=\"_blank\">Hohmann 等，Journal of Shoulder and Elbow Surgery，2023 年</a>。</li><li><strong>足底筋膜炎。</strong>二十一项试验：疼痛减轻程度大于皮质类固醇、冲击波治疗或安慰剂。<a href=\"https://doi.org/10.1016/j.fas.2024.02.004\" rel=\"noopener\" target=\"_blank\">Herber 等，Foot and Ankle Surgery，2024 年</a>。</li><li><strong>肌腱病总体情况。</strong>二十七项试验：在中期，疼痛和功能方面的结果优于皮质类固醇。<a href=\"https://doi.org/10.1186/s12891-025-08566-3\" rel=\"noopener\" target=\"_blank\">Ye 等，BMC Musculoskeletal Disorders，2025 年</a>。</li></ul>"),
  ("肩部手术：肩袖修复",
   "<p>二十三项试验，1,440 名患者：在关节镜修复过程中加用 PRP，可将再撕裂率从 29% 降至 16%，并改善疼痛和功能。<a href=\"https://doi.org/10.1016/j.arthro.2021.05.023\" rel=\"noopener\" target=\"_blank\">Li 等，Arthroscopy，2021 年</a>。</p>"),
  ("您还应当知道的事",
   "<ul><li><strong>并非所有研究都是有利的。</strong>一项澳大利亚试验纳入 288 名患者，发现在膝关节骨关节炎中 12 个月时与安慰剂没有差异。<a href=\"https://doi.org/10.1001/jama.2021.19415\" rel=\"noopener\" target=\"_blank\">Bennell 等，JAMA，2021 年</a>。</li><li><strong>在肌腱方面，证据质量较低</strong>，不及膝关节，一些综述发现与其他治疗没有明显差异。<a href=\"https://doi.org/10.2450/2022.0087-22\" rel=\"noopener\" target=\"_blank\">Masiello 等，Blood Transfusion，2022 年</a>。</li><li><strong>制剂很重要。</strong>PRP 有许多类型，并不都一样；这解释了不同研究之间的部分差异。</li><li><strong>并非对每位患者都有效。</strong>在经过良好筛选的病例中，以及与治疗性运动结合时，效果最好。</li></ul><p>因此，适应证总是在门诊经过体格检查和超声之后决定，并且从不保证一定有效果。</p>"),
 ],
 faq=[
  ("PRP 对膝关节骨关节炎有效是否已经得到证实？", "临床试验的综述和 2024 年欧洲共识都认为，它是轻中度骨关节炎的有效选择，缓解作用比透明质酸或皮质类固醇更明显、更持久。一些试验发现与安慰剂没有差异，因此患者的筛选是关键。"),
  ("它比皮质类固醇注射更好吗？", "皮质类固醇通常见效更快，在最初几周内。PRP 在中期，即 3 至 12 个月之间，在膝关节骨关节炎、网球肘、足底筋膜炎和臀肌肌腱病中结果更好。"),
  ("PRP 和生长因子是一回事吗？", "PRP 是这项治疗：取自患者自身血液的血小板浓缩物。生长因子是其血小板在受伤部位释放的蛋白质，因此这两个名称有时用来指同一种疗法。"),
 ]))
